import { LinkButton } from '@/components/ui/button';
import { Item, ItemActions, ItemContent, ItemMedia } from '@/components/ui/item';

/** A header link: its Writer label and where it goes. */
export interface SiteHeaderLink { label: string; href: string }

/** The inputs of `frames.site-header`: its three slots. */
export interface SiteHeaderInput {
  /** The `brand` slot: the host places the pinned `components.logo` here. */
  brand: React.ReactNode;
  /** The `nav` slot: the primary links and the navigation landmark's name. */
  nav?: { label?: string; items: readonly SiteHeaderLink[] };
  /** The `actions` slot: at most two buttons at the end of the bar. */
  actions?: readonly SiteHeaderLink[];
}

/** `frames.site-header`: the site banner, brand, primary navigation and actions on one stock aria-nova item row. */
export default function SiteHeaderFrame({ brand, nav, actions = [], ...provenance }: SiteHeaderInput & { [marker: `data-clossys-${string}`]: string }) {
  return <Item role="banner" {...provenance}>
    <ItemMedia>{brand}</ItemMedia>
    <ItemContent>
      {nav?.items.length ? <nav aria-label={nav.label || undefined}>
        {nav.items.map(link => <LinkButton key={link.href} href={link.href} variant="ghost" size="sm">{link.label}</LinkButton>)}
      </nav> : null}
    </ItemContent>
    {actions.length ? <ItemActions>
      {actions.slice(0, 2).map((action, index) => <LinkButton key={action.href} href={action.href} variant={index === 0 && actions.length > 1 ? 'ghost' : 'default'} size="sm">{action.label}</LinkButton>)}
    </ItemActions> : null}
  </Item>;
}
